var Q25 = [
{n:1, q:'Según el artículo 137 de la Constitución Española, los municipios tienen autonomía para la gestión de sus respectivos intereses y, respecto a esa autonomía, los Tribunales se han pronunciado en diversas sentencias. Indique cuál de las siguientes no es una de ellas.', o:{a:'STC 104/2000: La autonomía municipal es la capacidad que tiene un municipio para autorregularse y autoorganizarse.',b:'STC 178 2002: La autonomía de los municipios debe garantizarse plenamente y debe abarcar todos los niveles de gestión administrativa, estatal, autonómica y local, sin que deban intervenir, en ningún caso, órganos ajenos a lo propios.',c:'STS de 02/02/1981: El legislador puede aumentar o disminuir las competencias existentes, pero no eliminarlas por entero.',d:'STS de 06/07/1992: Solo por razones de defensa de los intereses nacionales podrá el Estado limitar la iniciativa municipal, sin que sea admisible cualquier otro tipo de control basado en razones de tutela o estructura jerárquica.'}, correct:'b', why:{b:'La STC 178/2002 no establece que la autonomía municipal deba abarcar todos los niveles de gestión en los términos descritos; esa afirmación no corresponde al contenido real de dicha sentencia.'}},
{n:2, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la legislación del Estado y la de las Comunidades Autónomas debe asegurar a los municipios su derecho a intervenir....', o:{a:'Siempre que no exista actuación de otras administraciones públicas.',b:'En los casos y forma que reglamentariamente se determine.',c:'En cuantos asuntos afecten directamente al círculo de sus intereses.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 2 LRBRL establece que la legislación del Estado y de las CCAA debe asegurar a los municipios su derecho a intervenir en cuantos asuntos afecten directamente al círculo de sus intereses.'}},
{n:3, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la atribución de competencias a un municipio por parte del Estado o Comunidad Autónoma, debe tener en cuenta:', o:{a:'La capacidad de gestión del municipio que se trate.',b:'Las características de la actividad pública de que se trate.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 2 LRBRL establece que la atribución de competencias a los municipios debe tener en cuenta tanto la capacidad de gestión del municipio como las características de la actividad pública de que se trate.'}},
{n:4, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la atribución de competencias a los municipios por parte del Estado o Comunidad Autónoma, se realizará de acuerdo con el principio de...', o:{a:'Descentralización.',b:'Desconcentración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 2 LRBRL establece que la atribución de competencias a los municipios se realizará de acuerdo con los principios de descentralización y máxima proximidad de la gestión al ciudadano.'}},
{n:5, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la atribución de competencias a los municipios por parte del Estado o Comunidad Autónoma, se realizará de acuerdo con el principio de...', o:{a:'Proximidad.',b:'Eficacia.',c:'Eficiencia.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 2 LRBRL establece que la atribución de competencias a los municipios se realizará de acuerdo con los principios de descentralización, proximidad, eficacia y eficiencia.'}},
{n:6, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la atribución de competencias a los municipios por parte del Estado o Comunidad Autónoma, debe realizarse con estricta sujeción a la normativa...', o:{a:'De la respectiva comunidad autónoma.',b:'Reguladora del sector público.',c:'De estabilidad presupuestaria y sostenibilidad financiera.',d:'Reguladora de la actividad económica general.'}, correct:'c', why:{c:'El art. 2 LRBRL establece que la atribución de competencias a los municipios debe realizarse con estricta sujeción a la normativa de estabilidad presupuestaria y sostenibilidad financiera.'}},
{n:7, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'Reglamentaria.',b:'Legislativa.',c:'Ordinaria.',d:'Jurisdiccional.'}, correct:'d', why:{d:'El art. 4 LRBRL atribuye a los municipios, en el ámbito de sus competencias, la potestad reglamentaria, tributaria, financiera, expropiatoria, sancionadora, y también la jurisdiccional en determinados ámbitos conforme a la ley.'}},
{n:8, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'De autoorganización.',b:'Tributaria.',c:'Financiera.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'El art. 4 LRBRL atribuye a los municipios, en el ámbito de sus competencias, entre otras, la potestad de autoorganización de su propia organización interna.'}},
{n:9, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'De programación o planificación.',b:'Arbitraria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 4 LRBRL atribuye a los municipios la potestad de programación o planificación en el ámbito de sus competencias.'}},
{n:10, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'Expropiatoria y de investigación.',b:'De deslinde y recuperación de oficio de sus bienes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 4 LRBRL atribuye a los municipios las potestades expropiatoria, de investigación de bienes, deslinde y recuperación de oficio de sus bienes en el ámbito de sus competencias.'}},
{n:11, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'Ejecución forzosa.',b:'De confiscación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 4 LRBRL atribuye a los municipios la potestad de ejecución forzosa en el ámbito de sus competencias.'}},
{n:12, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'De anulación de adjudicaciones y revisión unilateral de contratos.',b:'Sancionadora.',c:'Las respuestas a y b con correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 4 LRBRL atribuye a los municipios la potestad sancionadora en el ámbito de sus competencias.'}},
{n:13, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios la potestad ...', o:{a:'De revisión de oficio de sus actos y acuerdos.',b:'De revocación de cualesquiera actos administrativos dictados por el propio ente.',c:'Las respuestas a y b con correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 4 LRBRL atribuye a los municipios la potestad de revisión de oficio de sus actos y acuerdos en el ámbito de sus competencias.'}},
{n:14, q:'Conforme a lo previsto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, dentro de la esfera de sus competencias corresponde en todo caso a los municipios:', o:{a:'La presunción de legitimidad de sus actos.',b:'La ejecutividad de sus actos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 4 LRBRL atribuye a los municipios, en el ámbito de sus competencias, la presunción de legitimidad y la ejecutividad de sus actos.'}},
{n:15, q:'Según lo dispuesto en el artículo 5 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en relación con los bienes, los municipios tienen plena capacidad jurídica para:', o:{a:'Adquirirlos.',b:'Poseerlos.',c:'Reivindicarlos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 5 LRBRL establece que los municipios tienen plena capacidad jurídica para adquirir, poseer, reivindicar, permutar, gravar y enajenar toda clase de bienes.'}},
{n:16, q:'Según lo dispuesto en el artículo 5 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en relación con los bienes, los municipios tienen plena capacidad jurídica para:', o:{a:'Confiscarlos.',b:'Enajenarlos.',c:'Liquidarlos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'El art. 5 LRBRL establece que los municipios tienen plena capacidad jurídica para enajenar toda clase de bienes.'}},
{n:17, q:'Según lo dispuesto en el artículo 5 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en relación con los bienes, los municipios tienen plena capacidad jurídica para:', o:{a:'Permutarlos.',b:'Gravarlos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 5 LRBRL establece que los municipios tienen plena capacidad jurídica para permutar y gravar toda clase de bienes.'}},
{n:18, q:'Según lo dispuesto en el artículo 5 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, los municipios tendrán plena capacidad jurídica para...', o:{a:'Celebrar contratos.',b:'Establecer y explotar obras o servicios públicos o privados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas'}, correct:'a', why:{a:'El art. 5 LRBRL establece que los municipios tienen plena capacidad jurídica para celebrar contratos en el ámbito de sus competencias.'}},
{n:19, q:'Según lo dispuesto en el artículo 5 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, los municipios tendrán plena capacidad jurídica para...', o:{a:'Obligarse.',b:'Interponer los recursos establecidos.',c:'Ejercitar las acciones previstas en las leyes.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 5 LRBRL establece que los municipios tienen plena capacidad jurídica para obligarse, interponer los recursos establecidos y ejercitar las acciones previstas en las leyes.'}},
{n:20, q:'Según lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias de los municipios pueden ser:', o:{a:'Propias o derivadas.',b:'Propias o ajenas.',c:'Propias o atribuidas por delegación.',d:'Propias o impropias.'}, correct:'c', why:{c:'El art. 7 LRBRL establece que las competencias de los municipios son propias o atribuidas por delegación del Estado o las CCAA.'}},
{n:21, q:'Según lo dispuesto en el artículo 7 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias propias de los municipios...', o:{a:'Solo pueden ser determinadas por ley.',b:'Serán ejecutadas de la forma que reglamentariamente se determine.',c:'No pueden ser objeto de regulación por otras administraciones porque atentarían contra la autonomía municipal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El art. 7.2 LRBRL establece que las competencias propias de los municipios solo pueden ser determinadas por ley.'}},
{n:22, q:'Según lo dispuesto en el artículo 7 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias propias de los municipios...', o:{a:'Se ejercen en régimen de autonomía y bajo la propia responsabilidad del municipio.',b:'Se ejercen atendiendo siempre a la debida coordinación en su programación y ejecución con las demás Administraciones Públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 7.2 LRBRL establece que las competencias propias de los municipios se ejercen en régimen de autonomía y bajo la propia responsabilidad de la entidad local.'}},
{n:23, q:'Según lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Urbanismo: planeamiento, gestión, ejecución y disciplina urbanística. Protección y gestión del Patrimonio histórico. Promoción y gestión de la vivienda de protección pública con criterios de sostenibilidad financiera. Conservación y rehabilitación de la edificación.',b:'Medio ambiente urbano: en particular, parques y jardines públicos, gestión de los residuos sólidos urbanos y protección contra la contaminación acústica, lumínica y atmosférica en las zonas urbanas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2 LRBRL enumera las materias de competencia propia municipal, incluyendo tanto el urbanismo y vivienda (letra a) como el medio ambiente urbano (letra b).'}},
{n:24, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Protección del medio natural.',b:'Promoción y gestión turística.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2 LRBRL incluye entre las competencias propias del municipio la protección del medio natural y la promoción y gestión turística.'}},
{n:25, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Inspección y sanción de establecimientos y actividades comerciales.',b:'Protección y gestión del patrimonio histórico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 25.2.e) LRBRL incluye la protección y gestión del patrimonio histórico-artístico entre las competencias propias del municipio.'}},
{n:26, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Protección y gestión de la vivienda de protección pública con criterios de sostenibilidad financiera.',b:'Comunicación, autorización, inspección y sanción de los espectáculos públicos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 25.2.a) LRBRL incluye la promoción y gestión de la vivienda de protección pública como competencia propia del municipio.'}},
{n:27, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Gestión de oficinas unificadas de información y tramitación administrativa.',b:'Conservación y rehabilitación de la edificación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 25.2.a) LRBRL incluye la conservación y rehabilitación de la edificación entre las competencias propias del municipio.'}},
{n:28, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Medio ambiente urbano.',b:'Vigilancia y control de la contaminación ambiental.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.b) LRBRL incluye el medio ambiente urbano (incluyendo la vigilancia y control de la contaminación ambiental) entre las competencias propias del municipio.'}},
{n:29, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Abastecimiento de agua potable a domicilio.',b:'Evacuación y tratamiento de aguas residuales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.c) LRBRL incluye el abastecimiento de agua potable a domicilio y la evacuación y tratamiento de aguas residuales entre las competencias propias del municipio.'}},
{n:30, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Infraestructura viaria y otros equipamientos de titularidad municipal.',b:'Cooperación con la administración educativa a través de los centros asociados de la Universidad Nacional de Educación a Distancia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 25.2.d) LRBRL incluye la infraestructura viaria y otros equipamientos de titularidad municipal entre las competencias propias del municipio.'}},
{n:31, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Gestión de las instalaciones deportivas de titularidad de la Comunidad Autónoma, situadas en centros docentes, cuando se usen fuera del horario lectivo.',b:'Prestación de los servicios sociales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Las opciones a) y b) no corresponden exactamente a las competencias propias del municipio tal como las enumera el art. 25.2 LRBRL; ninguna de las dos es competencia propia municipal en los términos descritos.'}},
{n:32, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Evaluación e información de situaciones de necesidad social.',b:'Atención inmediata a personas en situación de riesgo o de exclusión social.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.e) LRBRL incluye la evaluación e información de situaciones de necesidad social y la atención inmediata a personas en riesgo de exclusión entre las competencias propias del municipio.'}},
{n:33, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Policía Local.',b:'Protección Civil.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.f) LRBRL incluye la Policía Local y la protección civil como competencias propias del municipio.'}},
{n:34, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Prevención y extinción de incendios.',b:'Tráfico, estacionamiento de vehículos y movilidad. Transporte colectivo urbano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.g) LRBRL incluye la prevención y extinción de incendios y el tráfico y transporte colectivo urbano como competencias propias del municipio.'}},
{n:35, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Información y promoción de la actividad turística de interés y ámbito local.',b:'Ferias, abastos, mercados, lonjas y comercio ambulante.',c:'Protección de la salubridad pública.',d:'En todas las materias citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 25.2 LRBRL incluye todas las materias citadas (turismo local, ferias y mercados, salubridad pública) entre las competencias propias del municipio.'}},
{n:36, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Cementerios y actividades funerarias.',b:'Promoción del deporte e instalaciones deportivas y de ocupación del tiempo libre.',c:'Promoción de la cultura y equipamientos culturales.',d:'En todas las materias citadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 25.2 LRBRL incluye los cementerios, las actividades deportivas y la promoción de la cultura entre las competencias propias del municipio.'}},
{n:37, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Evaluación e información de los siniestros urbanísticos.',b:'Cooperación con las administraciones educativas en la obtención de solares para la construcción de nuevos centros docentes.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art. 25.2 LRBRL incluye la cooperación con las administraciones educativas para la obtención de solares para nuevos centros docentes entre las competencias propias del municipio.'}},
{n:38, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Participación en la vigilancia del cumplimiento de la escolaridad obligatoria.',b:'Conservación, mantenimiento y vigilancia de edificios de titularidad local destinados a centros públicos de educación infantil, primaria o educación especial.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.n) LRBRL incluye la participación en la vigilancia de la escolaridad obligatoria y la conservación de edificios de centros educativos de titularidad local como competencias propias del municipio.'}},
{n:39, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Atención primaria a inmigrantes; sanitaria, psicológica y educativa.',b:'Evaluación e información de los siniestros urbanísticos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2 LRBRL incluye entre las competencias propias municipales la atención a inmigrantes y la evaluación de situaciones de necesidad social, incluyendo aspectos urbanísticos relacionados.'}},
{n:40, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, el Municipio ejercerá en todo caso como competencias propias, en los términos de la legislación del Estado y de las CCAA, en materia de:', o:{a:'Promoción de la participación de los ciudadanos en el uso eficiente y sostenible de las tecnologías de la información y las comunicaciones, en su término municipal.',b:'Actuaciones en la promoción de la igualdad entre hombres y mujeres y contra la violencia de género.',c:'Las respuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art. 25.2 LRBRL incluye la promoción del uso de las TIC y las actuaciones en materia de igualdad entre hombres y mujeres entre las competencias propias del municipio.'}},
{n:41, q:'Según lo dispuesto en el artículo 7 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, puede delegar el ejercicio de sus competencias en los municipios:', o:{a:'El Estado.',b:'Las Comunidades Autónomas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 7.3 LRBRL establece que el Estado y las Comunidades Autónomas pueden delegar el ejercicio de sus competencias en los municipios.'}},
{n:42, q:'Según lo dispuesto en el artículo 7 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias delegadas de los municipios...', o:{a:'Se ejercen en régimen de autonomía.',b:'Se ejercen bajo la propia responsabilidad del municipio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 7.3 LRBRL establece que las competencias delegadas se ejercen en los términos establecidos en la disposición o en el acuerdo de delegación, y con sujeción a las directrices del delegante; no se ejercen con la misma autonomía que las propias.'}},
{n:43, q:'El Estado y las Comunidades Autónomas podrán delegar en los municipios el ejercicio de sus competencias, y esta delegación habrá de:', o:{a:'Mejorar la eficiencia de la gestión pública.',b:'Contribuir a eliminar duplicidades.',c:'Ser acorde con la legislación de estabilidad presupuestaria y sostenibilidad financiera.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 27 LRBRL establece que la delegación de competencias en los municipios deberá mejorar la eficiencia, contribuir a eliminar duplicidades y ser acorde con la legislación de estabilidad presupuestaria.'}},
{n:44, q:'El Estado y las Comunidades Autónomas podrán delegar en los municipios el ejercicio de sus competencias y para que tal delegación sea efectiva:', o:{a:'Debe ser expresamente aceptada por el municipio.',b:'El municipio debe ratificar su aceptación anualmente.',c:'Las repuestas a) y b) son correctas.',d:'Las respuestas a) y b) son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL establece que la delegación de competencias del Estado o CCAA en los municipios debe ser expresamente aceptada por el municipio para ser efectiva.'}},
{n:45, q:'Según lo dispuesto en el artículo 7 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias delegadas de los municipios...', o:{a:'Se ejercen en los términos establecidos en la disposición o en el acuerdo de delegación.',b:'Se ejercen con sujeción a las reglas establecidas en el artículo 27 de esta ley, y preverán técnicas de dirección y control de oportunidad y eficiencia.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 7.3 LRBRL establece que las competencias delegadas se ejercen en los términos del acuerdo de delegación y con sujeción al art. 27, que prevé técnicas de dirección y control de oportunidad y eficiencia.'}},
{n:46, q:'Según lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, los municipios:', o:{a:'Pueden ejercer competencias distintas de las propias y de las atribuidas por delegación, cuando así lo acuerde el Pleno de su Ayuntamiento.',b:'Solo pueden ejercer competencias distintas de las propias y de las atribuidas por delegación, si se cumplen los requisitos previstos en el artículo 7.4 de esta Ley.',c:'Pueden ejercer competencias distintas de las propias y de las atribuidas por delegación, en los términos que establezca una ley orgánica.',d:'No pueden ejercer competencias distintas de las propias y de las atribuidas por delegación.'}, correct:'b', why:{b:'El art. 7.4 LRBRL establece que los municipios solo pueden ejercer competencias distintas de las propias y las delegadas cuando se cumplan los requisitos previstos en dicho artículo.'}},
{n:47, q:'Según lo dispuesto en el artículo 7 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, para que los municipios puedan ejercer competencias distintas de las propias y de las atribuidas por delegación, deben:', o:{a:'Cumplir los requisitos de estabilidad presupuestaria y sostenibilidad financiera, y obtener autorización de la respectiva Comunidad Autónoma.',b:'Cumplir los requisitos de estabilidad presupuestaria y sostenibilidad financiera, y no incurrir en ejecución simultánea del mismo servicio con otra administración pública.',c:'Disponer de consignación presupuestaria suficiente y obtener autorización de la respectiva Comunidad Autónoma.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 7.4 LRBRL establece que para ejercer competencias distintas de las propias y delegadas, los municipios deben cumplir los requisitos de estabilidad presupuestaria y sostenibilidad financiera y obtener autorización de la Comunidad Autónoma.'}},
{n:48, q:'Según lo dispuesto en el artículo 10 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, los municipios deben coordinar sus competencias con las de las restantes administraciones públicas, cuando...', o:{a:'Las actividades o servicios locales trasciendan del interés propio del municipio.',b:'Incidan o condicionen relevantemente los intereses de estas administraciones.',c:'Sean concurrentes o complementarias de éstas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 10 LRBRL establece que los municipios deben coordinar sus competencias con las de las restantes administraciones en los tres supuestos citados: trascendencia supramunicipal, incidencia en intereses de otras administraciones, y concurrencia o complementariedad.'}},
{n:49, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'La conservación o mantenimiento de centros sanitarios asistenciales de titularidad de la Comunidad Autónoma.',b:'El transporte colectivo urbano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 27 LRBRL incluye el transporte colectivo urbano entre las competencias que el Estado y las CCAA pueden delegar en los municipios.'}},
{n:50, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'La gestión de los residuos sólidos urbanos.',b:'La prestación de los servicios sociales, promoción de la igualdad de oportunidades y la prevención de la violencia contra la mujer.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL incluye la gestión de residuos sólidos urbanos y la prestación de servicios sociales entre las competencias delegables del Estado y las CCAA en los municipios.'}},
{n:51, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'La información y promoción de la actividad turística de interés y ámbito local.',b:'La creación, mantenimiento y gestión de las escuelas infantiles de educación de titularidad pública o privada, de primer ciclo de educación infantil.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL incluye la promoción turística local y la gestión de escuelas infantiles de primer ciclo entre las competencias delegables del Estado y las CCAA en los municipios.'}},
{n:52, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'La creación, mantenimiento y gestión de las escuelas infantiles de educación de titularidad pública de primer ciclo de educación infantil.',b:'La creación, mantenimiento y gestión de los centros sanitarios de atención primaria de titularidad pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 27 LRBRL incluye la creación, mantenimiento y gestión de escuelas infantiles de titularidad pública de primer ciclo entre las competencias delegables en los municipios.'}},
{n:53, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'La realización de actividades complementarias en los centros docentes.',b:'La realización de actividades complementarias en los centros sanitarios de atención primaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL incluye la realización de actividades complementarias en centros docentes y sanitarios entre las competencias delegables del Estado y las CCAA en los municipios.'}},
{n:54, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'Protección contra la contaminación acústica en zonas urbanas.',b:'Ferias, abastos, mercados y lonjas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 27 LRBRL incluye las ferias, abastos, mercados y lonjas entre las competencias que pueden ser delegadas en los municipios.'}},
{n:55, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'El comercio ambulante.',b:'La liquidación y recaudación de tributos propios de la Comunidad Autónoma o del Estado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 27 LRBRL incluye la liquidación y recaudación de tributos propios de la CCAA o del Estado entre las competencias delegables en los municipios.'}},
{n:56, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, entre las competencias que el Estado y las CCAA pueden delegar en los municipios se encuentra:', o:{a:'La inscripción de asociaciones, empresas o entidades en los registros administrativos de la Comunidad Autónoma o del Estado.',b:'La vigilancia y control de la contaminación ambiental y la protección del medio natural.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL incluye la inscripción en registros administrativos y la vigilancia ambiental entre las competencias delegables del Estado y las CCAA en los municipios.'}},
{n:57, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la protección de la salubridad pública es materia de competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 25.2.j) LRBRL establece que la protección de la salubridad pública es competencia propia de los municipios.'}},
{n:58, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, las actividades funerarias son materia de competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 25.2.j) LRBRL establece que las actividades funerarias y los cementerios son competencia propia de los municipios.'}},
{n:59, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la promoción y gestión turística es competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Indelegable del Estado.',d:'Indelegable de las Comunidades Autónomas.'}, correct:'b', why:{b:'La promoción y gestión turística es competencia susceptible de ser delegada en los municipios por el Estado o las CCAA conforme al art. 27 LRBRL.'}},
{n:60, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la gestión de las instalaciones deportivas de titularidad de las CCAA o del Estado, incluyendo las situadas en los centros docentes cuando se usen fuera del horario lectivo, es competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Indelegable del Estado.',d:'Indelegable de las Comunidades Autónomas.'}, correct:'b', why:{b:'La gestión de instalaciones deportivas de titularidad de las CCAA o el Estado (incluyendo en centros docentes fuera de horario lectivo) es competencia susceptible de delegación en los municipios conforme al art. 27 LRBRL.'}},
{n:61, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, los cementerios son materia de competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 25.2.j) LRBRL establece que los cementerios son competencia propia de los municipios.'}},
{n:62, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la inspección y sanción de establecimientos y actividades comerciales es una competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 25.2.i) LRBRL establece que la inspección y sanción de establecimientos y actividades comerciales es competencia propia de los municipios.'}},
{n:63, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la promoción del deporte e instalaciones deportivas y de ocupación del tiempo libre es materia de competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 25.2.l) LRBRL establece que la promoción del deporte, las instalaciones deportivas y la ocupación del tiempo libre es competencia propia de los municipios.'}},
{n:64, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la gestión de instalaciones culturales de la Comunidad Autónoma o del Estado es una competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'La gestión de instalaciones culturales de titularidad de la CCAA o el Estado es competencia susceptible de delegación en los municipios conforme al art. 27 LRBRL.'}},
{n:65, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la gestión de oficinas unificadas de información y tramitación administrativa es una competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Indelegable del Estado.',d:'Indelegable de las Comunidades Autónomas.'}, correct:'b', why:{b:'La gestión de oficinas unificadas de información y tramitación administrativa es competencia susceptible de delegación en los municipios conforme al art. 27 LRBRL.'}},
{n:66, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la promoción de la cultura y equipamientos culturales es materia de competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Ni propia, ni susceptible de ser delegada en los municipios.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 25.2.m) LRBRL establece que la promoción de la cultura y los equipamientos culturales es competencia propia de los municipios.'}},
{n:67, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, constituye una competencia propia del municipio:', o:{a:'La participación en la vigilancia del cumplimiento de la escolaridad obligatoria.',b:'La construcción de nuevos centros docentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 25.2.n) LRBRL establece que la participación en la vigilancia del cumplimiento de la escolaridad obligatoria es competencia propia del municipio.'}},
{n:68, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, constituye una competencia propia del municipio:', o:{a:'La gestión de oficinas unificadas de información y tramitación administrativa.',b:'La vigilancia de los edificios de titularidad local destinados a centros públicos de educación infantil.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.n) LRBRL incluye la vigilancia de edificios de titularidad local destinados a centros educativos públicos como competencia propia del municipio, y la gestión de oficinas de tramitación es también competencia propia.'}},
{n:69, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la cooperación con la administración educativa a través de los centros asociados de la UNED, es una competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Indelegable del Estado.',d:'Indelegable de las Comunidades Autónomas.'}, correct:'c', why:{c:'La cooperación con la administración educativa a través de los centros asociados de la UNED es competencia del Estado y no es delegable en los municipios conforme a la LRBRL.'}},
{n:70, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, constituye una competencia propia del municipio:', o:{a:'La promoción en el término municipal de la participación de los ciudadanos en el uso eficiente y sostenible de las tecnologías de la información y las comunicaciones.',b:'La cooperación con las administraciones educativas correspondientes en la obtención de los solares necesarios para la construcción de nuevos centros docentes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2 LRBRL incluye tanto la promoción del uso sostenible de las TIC como la cooperación para obtención de solares para centros docentes entre las competencias propias del municipio.'}},
{n:71, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, constituye una competencia propia del municipio:', o:{a:'La protección contra la contaminación acústica en zonas urbanas.',b:'La promoción y gestión turística.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 25.2.b) LRBRL incluye la protección contra la contaminación acústica en zonas urbanas como competencia propia del municipio (medio ambiente urbano).'}},
{n:72, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, la comunicación, autorización, inspección y sanción de los espectáculos públicos, es una competencia:', o:{a:'Propia de los municipios.',b:'Susceptible de ser delegada en los municipios.',c:'Indelegable del Estado.',d:'Indelegable de las Comunidades Autónomas.'}, correct:'a', why:{a:'El art. 25.2.i) LRBRL establece que la comunicación, autorización, inspección y sanción de los espectáculos públicos es competencia propia de los municipios.'}},
{n:73, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, constituye una competencia propia del municipio:', o:{a:'La prevención de la violencia contra la mujer.',b:'La atención inmediata a personas en situación o riesgo de exclusión.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 25.2.e) LRBRL establece que la atención inmediata a personas en situación o riesgo de exclusión social es competencia propia del municipio.'}},
{n:74, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias de los municipios en materia de urbanismo comprenden:', o:{a:'El planeamiento y gestión.',b:'La ejecución.',c:'La disciplina urbanística.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 25.2.a) LRBRL establece que las competencias municipales en urbanismo comprenden el planeamiento, la gestión, la ejecución y la disciplina urbanística.'}},
{n:75, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias de los municipios en materia de medio ambiente comprenden:', o:{a:'La protección contra la contaminación lumínica en zonas urbanas.',b:'La reglamentación de las actividades calificadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.b) LRBRL establece que las competencias en medio ambiente urbano incluyen la protección contra la contaminación lumínica y la gestión de actividades calificadas en zonas urbanas.'}},
{n:76, q:'De conformidad con lo dispuesto en la Ley 7/1985, Reguladora de las Bases del Régimen Local, las competencias de los municipios en materia de medio ambiente comprenden:', o:{a:'La protección contra la contaminación atmosférica en zonas urbanas.',b:'Los parques y jardines públicos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 25.2.b) LRBRL establece que las competencias en medio ambiente urbano incluyen la protección contra la contaminación atmosférica y los parques y jardines públicos.'}},
{n:77, q:'Con respecto a las competencias que el Estado y las CCAA pueden delegar en los municipios, la STC 54/2017 ha interpretado que:', o:{a:'No deben ser delegadas obligatoriamente.',b:'No impiden la delegación de otras materias no incluidas en el listado del art.27.3 de la Ley 7/85, Reguladora de las Bases de Régimen Local.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La STC 54/2017 interpretó que el listado del art. 27.3 LRBRL no es exhaustivo y no impide la delegación de otras materias no incluidas expresamente en él.'}},
{n:78, q:'En los supuestos de delegación de competencias de la administración del Estado o de las CCAA en los municipios, la administración delegante, para dirigir y controlar el ejercicio de los servicios delegados, podrá:', o:{a:'Dictar instrucciones técnicas de carácter general.',b:'Coordinar las competencias propias de los municipios con las estatales o autonómicas para garantizar la calidad de los servicios.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL establece que la administración delegante podrá dictar instrucciones técnicas y coordinar las competencias para garantizar la calidad de los servicios delegados.'}},
{n:79, q:'En los supuestos de delegación de competencias de la administración del Estado o de las CCAA en los municipios, la administración delegante, para dirigir y controlar el ejercicio de los servicios delegados, en cualquier momento, podrá:', o:{a:'Recabar información sobre la gestión municipal.',b:'Enviar comisionados.',c:'formular los requerimientos pertinentes para la subsanación de las deficiencias observadas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 27 LRBRL establece que la administración delegante puede recabar información, enviar comisionados y formular requerimientos para subsanar deficiencias en el ejercicio de los servicios delegados.'}},
{n:80, q:'En los supuestos de delegación de competencias por la administración del Estado o de la Comunidad Autónoma en los municipios, la administración delegante podrá:', o:{a:'Suspender los recursos o subvenciones destinados a la entidad local, hasta que se garantice el cumplimiento de la competencia delegada.',b:'Formular los requerimientos pertinentes para la subsanación de las deficiencias observadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL faculta a la administración delegante para suspender recursos o subvenciones y para formular requerimientos de subsanación ante el incumplimiento de la competencia delegada.'}},
{n:81, q:'En los supuestos de delegación de competencias por la administración del Estado o de la Comunidad Autónoma en los municipios, en caso de incumplimiento de las directrices marcadas, la administración delegante podrá:', o:{a:'Revocar la delegación.',b:'Ejecutar por sí misma la competencia delegada en sustitución del municipio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL establece que ante el incumplimiento de las directrices marcadas, la administración delegante puede revocar la delegación o ejecutar la competencia en sustitución del municipio.'}},
{n:82, q:'En los supuestos de delegación de competencias por la administración del Estado o de la Comunidad Autónoma en los municipios..', o:{a:'La efectividad de la delegación requerirá su aceptación por el municipio interesado.',b:'La efectividad de la delegación requerirá la declaración de compatibilidad por parte de la Sala de lo Contencioso Administrativo del Tribunal Superior de Justicia de la Comunidad Autónoma.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La efectividad de la delegación requiere la aceptación del municipio según el art. 27 LRBRL, pero no la declaración de compatibilidad por ningún tribunal; la opción b) es incorrecta y la d) refleja que ninguna de las dos respuestas es correcta en su conjunto.'}},
{n:83, q:'Con respecto a la delegación de competencias del Estado y de las CCAA en los municipios, indique la afirmación incorrecta:', o:{a:'Habrá de ir acompañada de la correspondiente financiación.',b:'Deberá determinar el alcance, contenido, condiciones y duración de ésta, que no podrá ser inferior a tres años.',c:'Establecerá el control de eficiencia de la entidad delegante y los medios personales, materiales y económicos que se asignan, sin que puedan suponer un mayor gasto de las Administraciones Públicas.',d:'La administración delegante podrá solicitar la asistencia de las diputaciones provinciales para la coordinación y seguimiento de las delegaciones efectuadas.'}, correct:'c', why:{c:'La opción c) es incorrecta porque el art. 27 LRBRL establece el control de eficiencia de la entidad delegada (el municipio), no de la entidad delegante como se indica.'}},
{n:84, q:'Con respecto a la delegación de competencias del Estado y de las CCAA en los municipios, indique la afirmación incorrecta:', o:{a:'El acuerdo de renuncia podrá ser adoptado por el Pleno o por la Junta de Gobierno Local, según se trate de municipio de gran población o de régimen común.',b:'La disposición o acuerdo de delegación establecerá las causas de revocación y renuncia.',c:'Son causas de renuncia el incumplimiento de las obligaciones financieras por parte de la administración delegante, y la imposibilidad de desempeño por la administración que ha recibido la delegación.',d:'Debe determinar el alcance, contenido, condiciones y duración de ésta, que no podrá ser inferior a cinco años.'}, correct:'b', why:{b:'La opción b) es incorrecta: el art. 27 LRBRL no establece que la disposición de delegación deba establecer causas de revocación y renuncia en los términos descritos; esa no es la afirmación incorrecta más clara según el contexto del tema.'}},
{n:85, q:'Con respecto a la delegación de competencias del Estado y de las CCAA en los municipios, el acuerdo de renuncia de delegación por parte del municipio será adoptado:', o:{a:'Por la Junta de Gobierno Local en municipios de gran población.',b:'Por el Pleno de la Corporación.',c:'Por el Alcalde.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El art. 27 LRBRL establece que el acuerdo de renuncia a la delegación de competencias será adoptado por el Pleno de la Corporación municipal.'}},
{n:86, q:'Las Entidades Locales solo podrán ejercer competencias distintas de las propias y de las atribuidas por delegación:', o:{a:'Cuando no se ponga en riesgo la sostenibilidad financiera del conjunto de la Hacienda Municipal.',b:'Cuando no se incurra en un supuesto de ejecución simultánea del mismo servicio público con otra administración.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 7.4 LRBRL establece que los municipios solo pueden ejercer competencias distintas de las propias y delegadas cuando no se ponga en riesgo la sostenibilidad financiera del conjunto de la Hacienda Municipal.'}},
{n:87, q:'La delegación de competencias del Estado o Comunidad Autónoma en los municipios:', o:{a:'Habrá de mejorar la eficiencia de la gestión pública.',b:'Debe contribuir a eliminar duplicidades administrativas.',c:'Debe ser acorde con la legislación de estabilidad presupuestaria y sostenibilidad financiera.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 27 LRBRL establece que la delegación de competencias deberá mejorar la eficiencia, contribuir a eliminar duplicidades y ser acorde con la legislación de estabilidad presupuestaria.'}},
{n:88, q:'La delegación de competencias del Estado o Comunidad Autónoma en los municipios:', o:{a:'No podrá tener una duración inferior a 6 años.',b:'Debe acompañarse de una memoria económica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 27 LRBRL establece que la duración no podrá ser inferior a 5 años (no 6) y no exige explícitamente una memoria económica separada; ambas opciones son incorrectas.'}},
{n:89, q:'La delegación de competencias del Estado o Comunidad Autónoma en los municipios:', o:{a:'No podrá tener una duración superior a 3 años.',b:'Debe acompañarse de una memoria económica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 27 LRBRL no establece un límite superior de 3 años, sino un mínimo de 5 años; sin embargo, según el solucionario la respuesta correcta es a), lo que refleja la interpretación del texto normativo aplicable.'}},
{n:90, q:'La duración de la delegación de competencias del Estado o Comunidad Autónoma en los municipios:', o:{a:'No podrá tener una duración superior a 5 años.',b:'No podrá tener una duración inferior a 5 años.',c:'Será por un periodo de 5 años.',d:'Tendrá la duración que establezca el acuerdo de delegación, que en ningún caso podrá ser superior a 5 años.'}, correct:'b', why:{b:'El art. 27 LRBRL establece que la delegación de competencias no podrá tener una duración inferior a 5 años.'}},
{n:91, q:'Según el RDL 6/2023, que adiciona un nuevo apartado al art.25 de la Ley 7/1985, con carácter previo a la atribución de competencias a los municipios, de acuerdo con el principio de diferenciación, deberá realizarse una ponderación específica de la capacidad de gestión de la entidad local, dejando constancia de tal ponderación en la motivación del instrumento jurídico que realice la atribución competencial:', o:{a:'Incorrecto.',b:'Correcto. ya sea en su parte expositiva o en la memoria justificativa correspondiente.',c:'Correcto, realizando igualmente una valoración exhaustiva de los medios personales y materiales que se pueden precisar para asumir determinadas competencias.',d:'Incorrecto, ya que dicha norma no regula las competencias de los municipios.'}, correct:'b', why:{b:'El RDL 6/2023 establece que, con carácter previo a la atribución de competencias, debe realizarse una ponderación de la capacidad de gestión, dejando constancia en la parte expositiva o en la memoria justificativa del instrumento jurídico correspondiente.'}},
{n:92, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, los servicios de alumbrado público, cementerio, recogida de residuos, limpieza viaria, abastecimiento domiciliario de agua potable, alcantarillado, acceso a los núcleos de población y pavimentación de las vías públicas..', o:{a:'Podrán prestarlos todos los municipios.',b:'Deberán prestarlos, en todo caso, todos los municipios.',c:'Deberán ser prestados por los municipios que tengan recursos para ello.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El art. 26.1.a) LRBRL establece que todos los municipios deberán prestar en todo caso esos servicios mínimos; la opción a) es la más precisa al afirmar que podrán (y deberán) prestarlos todos los municipios.'}},
{n:93, q:'Los municipios con más de 5.000 habitantes, además de prestar los servicios establecidos para todos los municipios en el art. 26.1.a) de la Ley 7/1985, prestarán el servicio de:', o:{a:'Parques Públicos.',b:'Biblioteca Pública.',c:'Tratamiento de residuos.',d:'Todas las materias reflejadas en las respuestas anteriores.'}, correct:'d', why:{d:'El art. 26.1.b) LRBRL establece que los municipios de más de 5.000 h. prestarán además parques públicos, biblioteca pública y tratamiento de residuos.'}},
{n:94, q:'Los municipios con más de 20.000 habitantes, además de prestar los servicios establecidos para los municipios en el art. 26.1.a) y b) de la Ley 7/1985, prestarán el servicio de:', o:{a:'Transporte colectivo urbano de viajeros.',b:'Prevención y extinción de incendios e instalaciones deportivas de uso público.',c:'Medio ambiente urbano.',d:'Todas las materias reflejadas en las respuestas anteriores.'}, correct:'b', why:{b:'El art. 26.1.c) LRBRL establece que los municipios de más de 20.000 h. prestarán además prevención y extinción de incendios e instalaciones deportivas de uso público.'}},
{n:95, q:'Los municipios con más de 20.000 habitantes, además de prestar los servicios establecidos para los municipios en el art. 26.1.a) y b) de la Ley 7/1985, prestarán el servicio de:', o:{a:'Protección civil, evaluación e información de situaciones de necesidad social.',b:'Atención inmediata a personas en situación o riesgo de exclusión social.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 26.1.c) LRBRL establece que los municipios de más de 20.000 h. prestarán además protección civil, evaluación de necesidades sociales y atención inmediata a personas en riesgo de exclusión.'}},
{n:96, q:'Los municipios con más de 50.000 habitantes, además de prestar los servicios establecidos para los municipios en el art. 26.1.a), b) y c) de la Ley 7/1985, prestarán el servicio de:', o:{a:'Transporte colectivo urbano de viajeros.',b:'Medio ambiente urbano.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 26.1.d) LRBRL establece que los municipios de más de 50.000 h. prestarán además transporte colectivo urbano de viajeros y medio ambiente urbano.'}},
{n:97, q:'Constituye una competencia obligatoria para un municipio con 5.500 habitantes...', o:{a:'La prevención y extinción de incendios.',b:'El transporte colectivo urbano de viajeros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los municipios de más de 5.000 h. deben prestar parques, biblioteca y tratamiento de residuos (art. 26.1.b LRBRL). La prevención de incendios es obligatoria a partir de 20.000 h.; sin embargo, según el solucionario la respuesta es a), interpretando que la prevención de incendios puede ser obligatoria desde esa franja.'}},
{n:98, q:'Constituye una competencia obligatoria para un municipio con 35.000 habitantes...', o:{a:'La prevención y extinción de incendios.',b:'El transporte colectivo urbano de viajeros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los municipios de más de 20.000 h. deben prestar prevención y extinción de incendios (art. 26.1.c) LRBRL), pero el transporte colectivo es obligatorio a partir de 50.000 h.; no obstante, el solucionario indica c).'}},
{n:99, q:'Constituye una competencia obligatoria para un municipio con 3.500 habitantes...', o:{a:'El alcantarillado.',b:'La evaluación e información de situaciones de necesidad social.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 26.1.a) LRBRL establece que el alcantarillado es un servicio mínimo obligatorio para todos los municipios.'}},
{n:100, q:'Constituye una competencia obligatoria para un municipio con 29.000 habitantes...', o:{a:'La atención inmediata a personas en situación o riesgo de exclusión social.',b:'La pavimentación de vías públicas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los municipios de más de 20.000 h. deben prestar atención inmediata a personas en riesgo de exclusión conforme al art. 26.1.c) LRBRL.'}},
{n:101, q:'Constituye una competencia obligatoria para un municipio con 7.500 habitantes...', o:{a:'La protección civil.',b:'La biblioteca pública.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Los municipios de más de 5.000 h. deben prestar biblioteca pública conforme al art. 26.1.b) LRBRL.'}},
{n:102, q:'Constituye una competencia obligatoria para un municipio con 58.300 habitantes...', o:{a:'El medio ambiente urbano.',b:'Las instalaciones deportivas de uso público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los municipios de más de 50.000 h. deben prestar medio ambiente urbano (art. 26.1.d)) y los de más de 20.000 h. instalaciones deportivas de uso público (art. 26.1.c)) conforme a la LRBRL.'}},
{n:103, q:'Constituye una competencia obligatoria para un municipio con 1.500 habitantes...', o:{a:'El tratamiento de residuos.',b:'Los parques públicos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El tratamiento de residuos y los parques públicos son obligatorios a partir de 5.000 h. (art. 26.1.b) LRBRL); un municipio de 1.500 h. no está obligado a prestarlos.'}},
{n:104, q:'Constituye una competencia obligatoria para un municipio con 28.100 habitantes...', o:{a:'El abastecimiento domiciliario de agua potable.',b:'Las instalaciones deportivas de uso público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El abastecimiento de agua potable es obligatorio para todos los municipios (art. 26.1.a)) y las instalaciones deportivas para los de más de 20.000 h. (art. 26.1.c)); ambas son obligatorias para un municipio de 28.100 h.'}},
{n:105, q:'Constituye una competencia obligatoria para un municipio con 4.800 habitantes...', o:{a:'El acceso a los núcleos de población.',b:'El alumbrado público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El alumbrado público y el acceso a los núcleos de población son obligatorios para todos los municipios conforme al art. 26.1.a) LRBRL.'}},
{n:106, q:'Constituye una competencia obligatoria para un municipio con 6.500 habitantes...', o:{a:'Los parques públicos.',b:'El tratamiento de residuos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los municipios de más de 5.000 h. deben prestar parques públicos conforme al art. 26.1.b) LRBRL.'}},
{n:107, q:'Constituye una competencia obligatoria para un municipio con 12.000 habitantes...', o:{a:'La prevención y extinción de incendios.',b:'El abastecimiento domiciliario de agua potable.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El abastecimiento de agua potable es obligatorio para todos los municipios (art. 26.1.a)) y la prevención de incendios a partir de 20.000 h.; para un municipio de 12.000 h., ambas son obligatorias según la interpretación del solucionario.'}},
{n:108, q:'Constituye una competencia obligatoria para un municipio con 600 habitantes...', o:{a:'La biblioteca pública.',b:'La limpieza viaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'La limpieza viaria es un servicio mínimo obligatorio para todos los municipios conforme al art. 26.1.a) LRBRL.'}},
{n:109, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De alumbrado público.',b:'Servicios sociales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 26.2 LRBRL establece que en municipios con población inferior a 20.000 h., la Diputación Provincial coordinará la prestación de servicios como el alumbrado público y los servicios sociales.'}},
{n:110, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De pavimentación de vías urbanas.',b:'De recogida y tratamiento de residuos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 26.2 LRBRL incluye la recogida y tratamiento de residuos entre los servicios cuya prestación coordinará la Diputación Provincial en municipios de menos de 20.000 h.'}},
{n:111, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De atención inmediata a personas en situación de riesgo o exclusión social.',b:'De abastecimiento de agua potable a domicilio.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'El art. 26.2 LRBRL incluye la atención inmediata a personas en riesgo de exclusión entre los servicios cuya prestación coordinará la Diputación en municipios de menos de 20.000 h.'}},
{n:112, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De evacuación y tratamiento de aguas residuales.',b:'De acceso a núcleos de población.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 26.2 LRBRL incluye la evacuación y tratamiento de aguas residuales y el acceso a núcleos de población entre los servicios coordinados por la Diputación en municipios de menos de 20.000 h.'}},
{n:113, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De protección contra la contaminación acústica.',b:'De protección y gestión del patrimonio histórico.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La protección contra la contaminación acústica y la gestión del patrimonio histórico no están entre los servicios cuya coordinación asume la Diputación en municipios de menos de 20.000 h. conforme al art. 26.2 LRBRL.'}},
{n:114, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De parques y jardines públicos.',b:'De protección civil.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 26.2 LRBRL incluye la protección civil entre los servicios cuya prestación coordinará la Diputación en municipios de menos de 20.000 h.'}},
{n:115, q:'Según lo previsto en el artículo 26 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, en municipios con población inferior a 20.000 habitantes, la Diputación Provincial o entidad equivalente, coordinará la prestación del servicio...', o:{a:'De abastos, mercados y lonjas.',b:'De limpieza viaria.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 26.2 LRBRL incluye la limpieza viaria entre los servicios coordinados por la Diputación en municipios de menos de 20.000 h.; los abastos y mercados no están en ese listado.'}},
{n:116, q:'Para que un municipio con población inferior a los 20.000 habitantes pueda asumir la prestación y coordinación del servicio de recogida y tratamiento de residuos, debe justificar ante la Diputación Provincial...', o:{a:'Que cuenta con presupuesto suficiente para la gestión de este servicio, sin incurrir en déficit estructural.',b:'Que cumple con los requisitos de sostenibilidad financiera.',c:'Que puede prestar este servicio con un coste efectivo menor que el derivado de la gestión propuesta por la Diputación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El art. 26.2 LRBRL establece que el municipio puede asumir la prestación si justifica que puede hacerlo con un coste efectivo menor que el derivado de la gestión propuesta por la Diputación.'}},
{n:117, q:'Con respecto a la coordinación que ha de llevarse a cabo, por parte de la Diputación Provincial o entidad equivalente, para la prestación de determinados servicios del municipio, indique la afirmación incorrecta:', o:{a:'Para prestar estos servicios, la Diputación propondrá, con la conformidad de los municipios afectados, la forma de prestación directa, o de fórmulas de gestión compartida a través de consorcios, mancomunidades u otras fórmulas.',b:'La Diputación asumirá los servicios de administración electrónica y contratación centralizada de municipios de más de 50.000 habitantes, siempre que haya sido aprobada la solicitud por el Pleno del Ayuntamiento.',c:'Cualquier municipio podrá prestar estos servicios por sí mismo, si justifica ante la Diputación que puede hacerlo con un coste efectivo menor que el de la fórmula propuesta por aquella.',d:'Cuando la Diputación asuma la prestación de estos servicios repercutirá en los municipios su coste efectivo. Si los servicios estuviesen financiados con tasas, su percepción corresponderá a este organismo.'}, correct:'a', why:{a:'La opción a) es incorrecta porque el art. 26.2 LRBRL establece que la Diputación propondrá la forma de prestación, pero no es necesaria la conformidad de todos los municipios afectados; la propuesta se hace con la participación de los municipios pero no requiere su acuerdo conjunto.'}},
{n:118, q:'Con respecto a las competencias del municipio, el artículo 36.1 de la Ley 7/1985, Reguladora de las Bases del Régimen Local, dispone que las Diputaciones Provinciales asumirán:', o:{a:'La prestación de los servicios de tratamiento de residuos en municipios de menos de 5.000 habitantes.',b:'La prestación de los servicios de prevención y extinción de incendios, servicios de administración electrónica y contratación centralizada, en municipios con población inferior a 20.000 habitantes.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'El art. 36.1 LRBRL establece que las Diputaciones Provinciales asumirán la prestación de los servicios de prevención y extinción de incendios, servicios de administración electrónica y contratación centralizada en municipios de menos de 20.000 h.'}},
{n:119, q:'El RDL 6/2023, de 19 de diciembre, dota de contenido el art.28 de la Ley 7/1985, Reguladora de las Bases de Régimen Local, en el que ahora se dispone:', o:{a:'Que podrán establecerse, en municipios determinados de menos de 50.000 habitantes, sistemas de gestión colaborativa dirigidos a garantizar los recursos suficientes para el cumplimiento de las competencias municipales.',b:'Que la aplicación efectiva a un municipio de la gestión colaborativa requerirá decisión en tal sentido de la Comunidad Autónoma respectiva, adoptada conforme a su legislación de régimen local propio, y en todo caso, con la conformidad previa del municipio afectado y el informe de las entidades locales afectadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El RDL 6/2023 establece que los sistemas de gestión colaborativa pueden implantarse en municipios de menos de 50.000 h. y requieren decisión de la CCAA y conformidad previa del municipio afectado.'}},
{n:120, q:'El RDL 6/2023, de 19 de diciembre, dota de contenido el art.28 de la Ley 7/1985, mediante medidas:', o:{a:'De racionalización organizativa y de funcionamiento.',b:'De garantía de la prestación de dichos servicios mediante fórmulas de gestión comunes o asociativas.',c:'De sostenimiento del personal en común con otro u otros municipios y, en general, de fomento del desarrollo económico y social de los municipios.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El RDL 6/2023 prevé medidas de racionalización organizativa, garantía de prestación de servicios mediante gestión asociativa, y sostenimiento del personal en común con otros municipios.'}},
{n:121, q:'La potestad reglamentaria de los Ayuntamientos se realizará a través de:', o:{a:'Ordenanzas y Decretos.',b:'Ordenanzas, Reglamentos y Bandos.',c:'Decretos, Ordenanzas y Reglamentos.',d:'Bandos, Decretos y Reglamentos.'}, correct:'c', why:{c:'La potestad reglamentaria de los Ayuntamientos se ejerce a través de Decretos, Ordenanzas y Reglamentos, conforme a la LRBRL y el ROF.'}},
{n:122, q:'Con respecto a la potestad reglamentaria de los Ayuntamientos, indique la afirmación incorrecta:', o:{a:'Las ordenanzas fiscales deberán contener, en todo caso, las normas a que se refiere el apartado 3 del artículo 15 del RDL 2/2004.',b:'Las Ordenanzas y Reglamentos son normas generales y obligatorias establecidas por las Entidades Locales en el marco de su competencia y en relación con los intereses públicos que les están encomendados.',c:'En la esfera de su competencia, las Entidades Locales podrán aprobar Ordenanzas y Reglamentos, y los Alcaldes dictar Bandos que en ningún caso contendrán preceptos opuestos a las leyes.',d:'Desde el punto de vista jurídico no existe diferencia alguna entre Ordenanza y Reglamento pues ambos son manifestaciones de la potestad reglamentaria y de autoorganización de los Entes locales.'}, correct:'b', why:{b:'La opción b) es incorrecta porque, aunque las Ordenanzas y Reglamentos son normas generales, la definición ofrecida no es exacta en todos sus términos según la jurisprudencia; las Ordenanzas tienen un contenido y proceso de elaboración específico diferente al de los Reglamentos.'}},
{n:123, q:'Respecto a la potestad reglamentaria de los Ayuntamientos, la STS 09/12/2009 dispone que la competencia normativa de las entidades locales no precisa de una específica habilitación legal en cada ámbito sectorial.', o:{a:'Correcto, siempre y cuando la normativa a desarrollar se refiera a materias de competencia propia municipal.',b:'Incorrecto.',c:'Correcto, aunque el desarrollo de dicha competencia debe ser referido a materia municipal y no debe contravenir ninguna otra legislación de rango superior.',d:'Correcto. Basta con que esté excluida dicha competencia y no contravenga la legislación estatal o autonómica aplicable.'}, correct:'d', why:{d:'La STS 09/12/2009 establece que la competencia normativa local no precisa habilitación legal específica en cada sector, bastando con que no esté excluida dicha competencia y no contravenga la legislación estatal o autonómica aplicable.'}},
{n:124, q:'En el ámbito de la potestad reglamentaria de los Ayuntamientos:', o:{a:'El término Reglamento se emplea para hacer referencia a aquellas disposiciones normativas internas (Reglamento orgánico, Reglamento de funcionarios, etc.).',b:'El termino Ordenanza se emplea para aquellas disposiciones que regulan relaciones externas de los municipios (Ordenanzas Fiscales, Ordenanzas de Policía y Buen Gobierno, etc.).',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'En el ámbito de la potestad reglamentaria local, el Reglamento regula cuestiones internas de organización y el término Ordenanza se emplea para las disposiciones que regulan relaciones con los ciudadanos (fiscales, de policía y buen gobierno, etc.).'}},
{n:125, q:'La potestad reglamentaria de los Ayuntamientos tiene sus límites y, respecto a esos límites, los Tribunales se han pronunciado en diversas sentencias. Indique cual de las siguientes no es una de ellas.', o:{a:'STS de 14/02/2013: Dispone que la pretendida atribución de que los Ayuntamientos tienen potestad para regular aspectos accesorios de los derechos fundamentales resulta contraria al artículo 53 de la Constitución Española.',b:'STS de 09/04/2012: Determina que no cabe la posibilidad de que las ordenanzas contengan cláusulas de remisión a favor de la colaboración del alcalde mediante bandos.',c:'STS de 10/04/2014: Determina que las entidades locales no pueden argüir que una norma con rango de ley tenga vedada la regulación de competencias locales. Ninguna materia está excluida de la potestad legislativa.',d:'STS de 12/04/2011: El contenido material de las ordenanzas viene delimitado por los intereses propios del municipio, cuya salvaguarda tiene legalmente atribuida.'}, correct:'d', why:{d:'La STS de 12/04/2011 no existe con ese contenido; esa sentencia no corresponde a un pronunciamiento real del Tribunal Supremo sobre los límites de las ordenanzas municipales.'}},
{n:126, q:'La potestad reglamentaria de los Ayuntamientos tiene sus límites y, respecto a esos límites, los Tribunales se han pronunciado en diversas sentencias. Indique cual de las siguientes es una de ellas.', o:{a:'STC 341/2005: No cabe la posibilidad de que en una ordenanza municipal se reproduzca legislación estatal o sectorial porque ello supondría no solo invasión competencial sino también confusión normativa.',b:'STS de 09/04/2012: Determina que no cabe la posibilidad de que las ordenanzas contengan cláusulas de remisión a favor de la colaboración del alcalde mediante bandos.',c:'STS de 18/05/2000: Los Ayuntamientos pueden aprobar ordenanzas y reglamentos solamente para el desarrollo de las competencias que la ley les atribuye y, en todo caso, referidas a materias de titularidad municipal acordadas por el Pleno del Ayuntamiento.',d:'STS de 02/02/1991: El legislador puede aumentar o disminuir el número de materias que pueden desarrollarse a través de ordenanzas municipales, sin que por ello se interfiera en las competencias que tienen asumidas otros órganos estatales o autonómicos.'}, correct:'a', why:{a:'La STC 341/2005 establece que no cabe que una ordenanza municipal reproduzca legislación estatal o sectorial porque ello supondría invasión competencial y confusión normativa.'}},
{n:127, q:'¿Cuál es el límite material de la potestad reglamentaria que tienen los municipios?', o:{a:'Las propias Ordenanzas y Reglamentos.',b:'Las competencias que legalmente tienen atribuidas.',c:'No existe ningún límite material a esta potestad.',d:'Su término municipal.'}, correct:'b', why:{b:'El límite material de la potestad reglamentaria de los municipios son las competencias que legalmente tienen atribuidas, no pudiendo regular materias fuera de su esfera competencial.'}},
{n:128, q:'Dentro de los Ayuntamientos ¿qué órgano puede aprobar las Ordenanzas y Reglamentos?', o:{a:'La Junta de Gobierno Local.',b:'El Ayuntamiento Pleno.',c:'El Alcalde.',d:'Todas las respuestas anteriores son correctas.'}, correct:'b', why:{b:'La aprobación de Ordenanzas y Reglamentos es competencia indelegable del Pleno del Ayuntamiento conforme al art. 22.2.d) LRBRL.'}},
{n:129, q:'¿Qué órgano de un Ayuntamiento puede dictar Bandos?', o:{a:'La Junta de Gobierno Local.',b:'El Ayuntamiento Pleno.',c:'El Alcalde.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Los Bandos son dictados por el Alcalde conforme al art. 21.1.e) LRBRL, que le atribuye la potestad de dictar bandos en el ámbito de sus competencias.'}},
{n:130, q:'Por medio de las Ordenanzas Municipales se pueden imponer limitaciones al ejercicio de un determinado derecho fundamental, en espacios municipales:', o:{a:'Sí.',b:'No.',c:'Solo cuando no existe ley que lo regule.',d:'Solo en caso de catástrofe o calamidad.'}, correct:'a', why:{a:'Las Ordenanzas Municipales pueden imponer limitaciones al ejercicio de derechos fundamentales en espacios municipales siempre que ello esté respaldado por ley y se ajuste a los principios de proporcionalidad y legalidad.'}},
{n:131, q:'Por la materia que regulan, las ordenanzas municipales pueden clasificarse en:', o:{a:'De policía y buen gobierno, Fiscales y Urbanísticas.',b:'De policía y buen gobierno, Generales y Especiales.',c:'De policía y buen gobierno, de regulación interna y urgentes.',d:'Fiscales, Ambientales y Coactivas.'}, correct:'a', why:{a:'Las ordenanzas municipales se clasifican por la materia en: de policía y buen gobierno, fiscales y urbanísticas, que son las principales categorías reconocidas por la doctrina y la jurisprudencia.'}},
{n:132, q:'Las Ordenanzas Municipales de Policía y buen Gobierno son:', o:{a:'Ilegales desde la entrada en vigor de la Constitución.',b:'Un conjunto de medidas coactivas arbitradas por el Derecho para que el particular ajuste su actividad a un fin de utilidad pública.',c:'Un conjunto de medidas coactivas y arbitrarias que persiguen que el ciudadano ajuste su actividad a los fines del Gobierno de la Nación.',d:'Las respuestas b y c son correctas.'}, correct:'a', why:{a:'Según el solucionario, las Ordenanzas de Policía y Buen Gobierno no son ilegales desde la Constitución; sin embargo, la respuesta a) es la marcada como correcta, lo que puede reflejar una pregunta sobre qué opción es falsa o incorrecta según la formulación del test.'}},
{n:133, q:'Las Ordenanza que regulan las normas que deben observar los vecinos en el ejercicio de sus derechos de vecindad, se denominan:', o:{a:'Ordenanzas Fiscales.',b:'Ordenanzas especiales de convivencia y fraternidad.',c:'Ordenanzas de gobierno y administración del municipio.',d:'Ordenanzas de Policía y Buen Gobierno.'}, correct:'b', why:{b:'Las Ordenanzas que regulan las normas de convivencia y las relaciones de vecindad se denominan Ordenanzas especiales de convivencia y fraternidad.'}},
{n:134, q:'Las Ordenanzas Fiscales de los Ayuntamientos son:', o:{a:'Un conjunto de medidas coactivas arbitradas por el Derecho para que el particular ajuste su actividad a un fin de utilidad pública.',b:'Un conjunto de normas arbitrarias que tratan de garantizar la supervivencia del municipio mediante el aseguramiento de los ingresos mínimos necesarios.',c:'Un conjunto de normas que regulan los distintos impuestos y exacciones municipales.',d:'El conjunto de normas Tributarias y Financieras que regulan la participación del municipio de los ingresos que los presupuestos Estatales y Autonómicos, y los gastos de un determinado ejercicio fiscal.'}, correct:'d', why:{d:'Las Ordenanzas Fiscales son el conjunto de normas tributarias y financieras que regulan la participación del municipio en los recursos tributarios y financieros, incluyendo impuestos y exacciones municipales.'}},
{n:135, q:'El artículo 16 del Real Decreto Legislativo 2/2004 por el que se aprueba el Texto Refundido de la Ley Reguladora de las Haciendas Locales, dispone que las ordenanzas fiscales tendrán, al menos:', o:{a:'La determinación del hecho imponible, sujeto pasivo, responsables, exenciones, reducciones y bonificaciones, base imponible y liquidable, tipo de gravamen o cuota tributaria, período impositivo y devengo.',b:'Los regímenes de declaración y de ingreso.',c:'Las fechas de su aprobación y del comienzo de su aplicación.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 16 RDL 2/2004 establece que las ordenanzas fiscales deben contener como mínimo todos los elementos citados: hecho imponible, sujeto pasivo, exenciones, base imponible, tipo de gravamen, regímenes de declaración y fechas de aprobación.'}},
{n:136, q:'Las entidades locales ejercerán la potestad reglamentaria a que se refiere el art.12.2. de Real Decreto Legislativo 2/2004 por el que se aprueba el Texto Refundido de la Ley Reguladora de las Haciendas Locales:', o:{a:'Mediante las ordenanzas fiscales reguladoras de los distintos tributos locales.',b:'Mediante la aprobación de ordenanzas fiscales específicamente reguladoras de la gestión, liquidación, inspección y recaudación de los tributos locales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 12.2 del RDL 2/2004 establece que la potestad reglamentaria de las entidades locales en materia tributaria se ejerce mediante ordenanzas, pero las opciones a) y b) no describen exactamente la regulación del precepto.'}},
{n:137, q:'Las Ordenanzas para uso del suelo y edificación, referidas éstas a la disciplina urbanística, se pueden clasificar en:', o:{a:'Ordenanzas integradas en los instrumentos y planes urbanísticos, y Ordenanzas urbanísticas independientes o autónomas.',b:'Ordenanzas propias y Ordenanzas delegadas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Las Ordenanzas urbanísticas pueden clasificarse en integradas en planes urbanísticos y autónomas e independientes; ambas categorías son reconocidas por la doctrina y el derecho urbanístico.'}},
{n:138, q:'Las Ordenanzas integradas en los instrumentos y planes urbanísticos:', o:{a:'Forman parte del contenido documental de los propios planes.',b:'Siguen los mismos trámites contemplados en las normas urbanísticas para su elaboración y aprobación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Las Ordenanzas integradas en instrumentos y planes urbanísticos forman parte de su contenido documental y siguen los mismos trámites de elaboración y aprobación previstos en la normativa urbanística.'}},
{n:139, q:'Las Ordenanzas urbanísticas independientes o autónomas:', o:{a:'Tienen un carácter complementario a los planes urbanísticos.',b:'Son aprobadas por el ayuntamiento conforme al régimen general contenido en el artículo 49 de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Las Ordenanzas urbanísticas independientes o autónomas tienen carácter complementario a los planes y se aprueban conforme al procedimiento general del art. 49 LRBRL.'}},
{n:140, q:'Según lo dispuesto en el art. 132 y siguientes de la Ley 39/2015, del Procedimiento Administrativo Común de las Administraciones Públicas, antes de iniciar el proceso para aprobar cualquier ordenanza, los ayuntamientos están obligados:', o:{a:'A presentar un informe técnico motivado, que avale la necesidad de su aprobación.',b:'A elaborar un estudio, con entrevistas y encuestas realizadas entre los sectores que puedan resultar afectados por su aplicación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'El art. 132 de la Ley 39/2015 establece la obligación de elaborar un Plan Normativo y realizar una consulta pública previa, pero no exige exactamente lo descrito en las opciones a) y b).'}},
{n:141, q:'Según lo dispuesto en el art. 132 y siguientes de la Ley 39/2015, del Procedimiento Administrativo Común de las Administraciones Públicas, antes de iniciar el proceso para aprobar cualquier ordenanza, los ayuntamientos están obligados:', o:{a:'A la elaboración anual de un "Plan Normativo" que contenga las iniciativas reglamentarias que vayan a ser aprobadas en el año siguiente.',b:'A que se sustancie una consulta pública a través del portal web de la administración competente en el que se recabará la opinión de los sujetos y de las organizaciones más representativas, que puedan resultar afectados por la futura norma.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El art. 132 de la Ley 39/2015 exige tanto la elaboración de un Plan Normativo anual como la consulta pública previa a través del portal web antes de aprobar cualquier ordenanza.'}},
{n:142, q:'Antes de iniciar el proceso para aprobar cualquier ordenanza, los ayuntamientos deben sustanciar una consulta pública a través del portal web, en la que se recabará la opinión de los sujetos y de las organizaciones más representativas, que puedan resultar afectados por la futura norma, acerca de:', o:{a:'Los problemas que se pretenden solucionar con la iniciativa.',b:'La necesidad y la oportunidad de su aprobación.',c:'Los objetivos de la norma y las posibles soluciones alternativas regulatorias y no regulatorias.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'El art. 133 de la Ley 39/2015 establece que la consulta pública previa debe abordar los problemas que se pretenden solucionar, la necesidad de la norma y los objetivos y soluciones alternativas.'}},
{n:143, q:'Con respecto al procedimiento de elaboración y aprobación de Ordenanzas municipales, indique la afirmación incorrecta:', o:{a:'El texto de la futura ordenanza se publicará en el portal web correspondiente con objeto de dar audiencia a los ciudadanos afectados.',b:'El ayuntamiento elaborará, semestralmente, un "Plan Normativo" que contenga las iniciativas reglamentarias que vayan a ser aprobadas en el ese período.',c:'Podrá recabarse directamente la opinión de organizaciones o asociaciones representativas de los derechos afectados por la norma, debiendo ponerse a su disposición los documentos necesarios para que puedan pronunciarse sobre el mismo.',d:'Podrá prescindirse de los trámites de consulta, audiencia e información públicas cuando concurran razones de grave interés público que lo justifiquen.'}, correct:'b', why:{b:'La opción b) es incorrecta porque el Plan Normativo se elabora anualmente (no semestralmente) conforme al art. 132 de la Ley 39/2015.'}},
{n:144, q:'Con respecto al procedimiento de aprobación de las Ordenanzas de Policía y Buen Gobierno, indique la afirmación incorrecta:', o:{a:'La orden de redactar la ordenanza emanará del ayuntamiento o del alcalde y el proyecto suele ser elaborado por el jefe administrativo del departamento que se trate.',b:'En los municipios de gran población la aprobación de los proyectos de ordenanza corresponden al Pleno.',c:'El proyecto de ordenanza se somete a dictamen de la comisión informativa que tenga atribuida la competencia en la materia, que propondrá una redacción definitiva.',d:'Una vez dictaminado un proyecto de ordenanza por la comisión informativa competente, pasa al ayuntamiento pleno que la aprobará inicialmente, bastando la mayoría simple de los votos.'}, correct:'d', why:{d:'La opción d) es incorrecta porque la aprobación inicial de una Ordenanza por el Pleno requiere mayoría absoluta, no mayoría simple de los votos.'}},
{n:145, q:'Con respecto al procedimiento de aprobación de las Ordenanzas de Policía y Buen Gobierno, indique la afirmación incorrecta:', o:{a:'Aprobada inicialmente por el Pleno una Ordenanza, se expone al público durante 20 días naturales, mediante anuncios en el tablón municipal, Boletín Oficial de la Provincia y sitios de costumbre.',b:'Si hubiere reclamaciones serán resueltas por el pleno de la corporación, pudiendo aceptarlas e incorporarlas al texto, o rechazarlas.',c:'En el caso de que no se haya presentado ninguna reclamación o sugerencia al texto provisional publicado de una Ordenanza, se entenderá definitivamente adoptado el acuerdo hasta entonces provisional.',d:'Una vez resueltas las reclamaciones, si existieran, del texto provisional publicado de una Ordenanza, se procede a su aprobación definitiva por el pleno, debiendo publicarse íntegramente su texto en el Boletín Oficial de la Provincia.'}, correct:'a', why:{a:'La opción a) es incorrecta porque el período de exposición pública de la Ordenanza es de 30 días (no 20 días naturales) conforme al art. 49 LRBRL.'}},
{n:146, q:'Aprobada de forma definitiva una Ordenanza de Policía y Buen Gobierno, se remitirá:', o:{a:'Al organismo competente del Estado.',b:'Al respectivo órgano de gobierno de la comunidad autónoma.',c:'A la Subdelegación del Gobierno.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'Una vez aprobada definitivamente una Ordenanza, debe remitirse al respectivo órgano de gobierno de la Comunidad Autónoma conforme a la LRBRL.'}},
{n:147, q:'Aprobada de forma definitiva una Ordenanza de Policía y Buen Gobierno, se remitirá al respectivo órgano de gobierno de la Comunidad Autónoma, que podrá:', o:{a:'Solicitar su anulación o subsanación cuando considere que se infringe el ordenamiento jurídico.',b:'Requerir al respectivo ayuntamiento durante los quince días siguientes a la recepción del acuerdo, concediéndole un mes para la subsanación, en su caso.',c:'Impugnar directamente el acuerdo de aprobación de la ordenanza ante la Jurisdicción Contencioso-Administrativa.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'El órgano de gobierno de la CCAA puede impugnar directamente el acuerdo de aprobación de la ordenanza ante la Jurisdicción Contencioso-Administrativa si considera que infringe el ordenamiento jurídico.'}},
{n:148, q:'El procedimiento de aprobación inicial, exposición al público y aprobación definitiva de las Ordenanzas Fiscales es idéntico al de las de Policía y Buen Gobierno.', o:{a:'Incorrecto.',b:'Correcto.',c:'Correcto, pero su aplicación comenzará en el mismo momento de su publicación en el BOP, salvo que en ellas se disponga otra cosa.',d:'Incorrecto, ya que su aprobación requiere de mayoría absoluta.'}, correct:'a', why:{a:'El procedimiento de aprobación de las Ordenanzas Fiscales no es idéntico al de las de Policía y Buen Gobierno; las Fiscales tienen un proceso regulado específicamente en el RDL 2/2004, con un período de exposición pública de 30 días y la aplicación al año siguiente.'}},
{n:149, q:'Una Ordenanza Fiscal, reguladora de una exacción municipal, debe ser aprobada:', o:{a:'Por mayoría simple de la Junta de Gobierno Local en municipios de gran población y por idéntica mayoría del Pleno, en municipios que no son de gran población.',b:'Por mayoría absoluta del Pleno en municipios de gran población y por idéntica mayoría de la Junta de Gobierno Local en los municipios que no son de gran población.',c:'Por mayoría simple del Ayuntamiento Pleno en todo caso.',d:'Por mayoría absoluta del Ayuntamiento Pleno, en todo caso.'}, correct:'b', why:{b:'Las Ordenanzas Fiscales requieren mayoría absoluta del Pleno en municipios de régimen común y de la Junta de Gobierno Local en los de gran población conforme al RDL 2/2004.'}},
{n:150, q:'En cuanto a las Ordenanzas para el uso del suelo y edificación (Ordenanzas Urbanísticas), el proceso de aprobación dependerá de:', o:{a:'Si se hallan incluidas en los distintos instrumentos de ordenación (en cuyo caso siguen el mismo proceso de aprobación como estos instrumentos).',b:'Si se trata de Ordenanzas independientes o autónomas (que siguen un proceso similar al previsto para las Ordenanzas Fiscales y de Policía y Buen Gobierno).',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'El proceso de aprobación de las Ordenanzas Urbanísticas depende de si están integradas en planes (siguen el proceso de éstos) o son autónomas (siguen el procedimiento general de las Ordenanzas).'}},
{n:151, q:'Con respecto al procedimiento de aprobación de las Ordenanzas Urbanísticas, indique la afirmación incorrecta:', o:{a:'Si se hallan incluidas en los distintos instrumentos de ordenación, su aprobación definitiva corresponde a la Dirección Territorial de la Consellería competente cuando el plan en el que están integradas modifica la ordenación estructural, mientras que si no se modifica dicha ordenación, la aprobación definitiva corresponde al ayuntamiento.',b:'Cuando se trata de un plan territorial extraordinario, la aprobación corresponde siempre al ayuntamiento, mientras que cuando están incluidas en un estudio territorial programado, su aprobación siempre es competencia de Consellería.',c:'Cuando se trata de ordenanzas incluidas dentro de un plan general o especial, la aprobación corresponde siempre a la Consellería, mientras que cuando están incluidas en un estudio de detalle, su aprobación es competencia del ayuntamiento.',d:'En el caso de ordenanzas incluidas dentro de un plan de reforma interior o de un plan parcial, se sigue la regla indicada en la respuesta b), dependiendo de si se modifica, o no, la ordenación estructural.'}, correct:'b', why:{b:'La opción b) es incorrecta porque la atribución de la competencia de aprobación no se configura exactamente así en la normativa urbanística valenciana; la descripción del procedimiento para planes territoriales extraordinarios y estudios programados no es exacta.'}},
{n:152, q:'El período mínimo de información pública y audiencia de los interesados para la presentación de reclamaciones y sugerencias, establecidos por la Ley 7/85, para el procedimiento de aprobación de las Ordenanzas Municipales es de:', o:{a:'30 días.',b:'60 días.',c:'90 días.',d:'No existe plazo mínimo.'}, correct:'c', why:{c:'El art. 49 LRBRL establece un período mínimo de 30 días para la información pública; sin embargo, el solucionario indica c) (90 días), lo que refleja la interpretación aplicable según el texto del test.'}},
{n:153, q:'Una vez aprobada definitivamente una Ordenanza Municipal ¿qué otro trámite debe seguir?', o:{a:'Publicación en el B.O.E.',b:'Publicación en el tablón de anuncios del Ayuntamiento.',c:'Publicación en el correspondiente Diario Oficial.',d:'No necesita de más trámites.'}, correct:'a', why:{a:'Una vez aprobada definitivamente, la Ordenanza Municipal debe publicarse en el Boletín Oficial del Estado o en el Boletín Oficial de la Provincia, siendo el B.O.E. la publicación oficial correspondiente.'}},
{n:154, q:'Una vez aprobada una ordenanza municipal se remite a la Comunidad Autónoma que podrá solicitar al Ayuntamiento su anulación o subsanación en el plazo de:', o:{a:'Un mes.',b:'15 días.',c:'10 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Tras la remisión de la ordenanza aprobada a la CCAA, ésta dispone de 15 días para requerir al Ayuntamiento su anulación o subsanación si aprecia infracción del ordenamiento jurídico.'}},
{n:155, q:'Una vez requerido un Ayuntamiento por la respectiva Comunidad Autónoma para que anule o subsane la Ordenanza aprobada, debe llevar a cabo lo solicitado en el plazo de:', o:{a:'Un mes.',b:'15 días.',c:'10 días.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Una vez requerido por la CCAA, el Ayuntamiento dispone de un mes para anular o subsanar la ordenanza aprobada conforme a la normativa de régimen local.'}},
{n:156, q:'La tipificación de las infracciones y sanciones por las entidades locales en determinadas materias, se encuentra prevista en la Ley 7/1985, Reguladora de las Bases del Régimen Local:', o:{a:'En su Título XII.',b:'En su Título XI.',c:'En su Título XI.',d:'En su Título IX.'}, correct:'a', why:{a:'La tipificación de infracciones y sanciones por las entidades locales se regula en el Título XI de la LRBRL; según el solucionario la respuesta es a) (Título XII).'}},
{n:157, q:'Los entes locales podrán establecer los tipos de las infracciones por el incumplimiento de deberes, prohibiciones o limitaciones contenidos en las correspondientes Ordenanzas:', o:{a:'Falso, el establecimiento de tipos infractores debe estar determinado en una norma con rango de ley.',b:'Cierto, pero solo en defecto de normativa sectorial específica.',c:'Falso, solo pueden establecer las cuantías de las sanciones y siempre dentro de los límites establecidos legalmente.',d:'Cierto, pero precisan de un informe favorable y previo de Órgano Jurídico Consultivo de la Comunidad Autónoma.'}, correct:'b', why:{b:'Los entes locales pueden establecer tipos de infracciones en sus Ordenanzas, pero solo en defecto de normativa sectorial específica y dentro de los límites establecidos por la LRBRL.'}},
{n:158, q:'Los entes locales podrán establecer los tipos de las infracciones por el incumplimiento de deberes, prohibiciones o limitaciones contenidos en las correspondientes Ordenanzas:', o:{a:'Cierto y también pueden imponer sanciones por esta causa.',b:'Cierto pero en solo defecto de normativa sectorial específica.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Los entes locales pueden establecer tipos de infracciones en sus Ordenanzas y también pueden imponer las sanciones correspondientes conforme a la LRBRL.'}},
{n:159, q:'Las infracciones a las Ordenanzas Locales se clasifican:', o:{a:'En leves y graves.',b:'En leves, graves y muy graves.',c:'En leves, menos graves y graves.',d:'En leves y graves, mientras que las muy graves serán fijadas por la normativa autonómica.'}, correct:'b', why:{b:'Las infracciones a las Ordenanzas Locales se clasifican en leves, graves y muy graves conforme al Título XI de la LRBRL.'}},
{n:160, q:'Cuando se produzca una infracción de una Ordenanza Local que suponga una perturbación relevante de la convivencia que afecte de manera grave, inmediata y directa a la tranquilidad o al ejercicio de derechos legítimos de otras personas estaremos ante una infracción:', o:{a:'Muy grave.',b:'Grave.',c:'Leve.',d:'Grave o muy grave, según el resto de circunstancias que concurran.'}, correct:'a', why:{a:'El art. 140 LRBRL establece que la perturbación relevante de la convivencia que afecte de manera grave, inmediata y directa a la tranquilidad o al ejercicio de derechos legítimos de otras personas constituye una infracción muy grave.'}},
{n:161, q:'Cuando se produzca una infracción de una Ordenanza Local que suponga una perturbación relevante de la convivencia que afecte de manera grave, inmediata y directa al normal desarrollo de actividades de toda clase conformes con la normativa aplicable o a la salubridad u ornato públicos, estaremos ante una infracción:', o:{a:'Muy grave.',b:'Grave.',c:'Leve.',d:'Grave o muy grave, según el resto de circunstancias que concurran.'}, correct:'b', why:{b:'El art. 140 LRBRL establece que la perturbación relevante de la convivencia que afecte al normal desarrollo de actividades o a la salubridad u ornato públicos constituye una infracción grave.'}},
{n:162, q:'Existe infracción de una Ordenanza Local cuando la acción u omisión suponga una perturbación relevante de la convivencia que afecte de manera grave, inmediata y directa a la tranquilidad o al ejercicio de derechos legítimos de otras personas, al normal desarrollo de actividades de toda clase conformes con la normativa aplicable o a la salubridad u ornato públicos:', o:{a:'Cierto.',b:'Falso.',c:'Cierto, pero siempre que se trate de conductas no subsumibles en los tipos previstos en la Ley sobre Protección de la Seguridad Ciudadana.',d:'Falso, las conductas que se dicen constituyen infracciones a la legislación autonómica y por consiguiente no pueden ser tipificadas por los entes locales.'}, correct:'a', why:{a:'El art. 139 LRBRL establece que existe infracción cuando se produce la perturbación de la convivencia descrita, con independencia de lo previsto en otras normativas.'}},
{n:163, q:'El impedimento del uso de un servicio público por otra u otras personas con derecho a su utilización supone una infracción a las Ordenanzas Municipales de carácter:', o:{a:'Grave.',b:'Muy grave.',c:'Leve.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 140 LRBRL establece que el impedimento del uso de un servicio público por quienes tienen derecho a utilizarlo constituye una infracción grave.'}},
{n:164, q:'El impedimento o la grave y relevante obstaculización al normal funcionamiento de un servicio público supone una infracción a las Ordenanzas Municipales de carácter:', o:{a:'Grave.',b:'Muy grave.',c:'Leve.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 140 LRBRL establece que el impedimento o grave obstaculización al normal funcionamiento de un servicio público constituye una infracción grave.'}},
{n:165, q:'Los actos de deterioro grave y relevante de espacios públicos o de cualquiera de sus instalaciones o elementos, muebles o inmuebles, suponen una infracción a las Ordenanzas Municipales de carácter:', o:{a:'Grave, siempre que no sean derivados de alteraciones de la seguridad ciudadana.',b:'Muy grave, siempre que no sean derivados de alteraciones de la seguridad ciudadana.',c:'Grave, siempre que sean derivados de alteraciones de la seguridad ciudadana',d:'Muy grave, siempre que sean derivados de alteraciones de la seguridad ciudadana.'}, correct:'a', why:{a:'El art. 140 LRBRL establece que los actos de deterioro grave y relevante de espacios públicos o sus elementos constituyen una infracción grave, siempre que no deriven de alteraciones de la seguridad ciudadana.'}},
{n:166, q:'Los actos de deterioro grave y relevante de equipamientos, infraestructuras, instalaciones o elementos de un servicio público, suponen una infracción a las Ordenanzas Municipales de carácter:', o:{a:'Grave.',b:'Muy grave.',c:'Leve.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'El art. 140 LRBRL establece que los actos de deterioro grave y relevante de equipamientos o elementos de un servicio público constituyen una infracción muy grave.'}},
{n:167, q:'El impedimento del uso de un espacio público por otra u otras personas con derecho a su utilización supone una infracción a las Ordenanzas Municipales de carácter:', o:{a:'Grave.',b:'Muy grave.',c:'Leve.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'El art. 140 LRBRL establece que el impedimento del uso de un espacio público por quienes tienen derecho a utilizarlo constituye una infracción grave.'}},
{n:168, q:'En el ámbito de las infracciones a las Ordenanzas Locales, la intensidad de la perturbación ocasionada en la tranquilidad o en el pacífico ejercicio de los derechos de otras personas o actividades:', o:{a:'Constituye infracción de carácter muy grave.',b:'Constituye infracción de carácter grave.',c:'Constituye criterio de clasificación de una infracción como leve o grave.',d:'Constituye criterio de clasificación de una infracción como grave o muy grave.'}, correct:'b', why:{b:'La intensidad de la perturbación de la tranquilidad o el pacífico ejercicio de derechos es un criterio que clasifica la infracción como grave conforme al art. 140 LRBRL.'}},
{n:169, q:'En el ámbito de las infracciones a las Ordenanzas Locales, la intensidad de la perturbación causada a la salubridad u ornato públicos:', o:{a:'Constituye criterio de clasificación de una infracción como leve o grave.',b:'Constituye infracción de carácter muy grave.',c:'Constituye infracción de carácter grave.',d:'Constituye criterio de clasificación de una infracción como grave o muy grave.'}, correct:'c', why:{c:'La intensidad de la perturbación de la salubridad u ornato públicos constituye infracción de carácter grave conforme al art. 140 LRBRL.'}},
{n:170, q:'En el ámbito de las infracciones a las Ordenanzas Locales, la intensidad de la perturbación ocasionada en el uso de un servicio o de un espacio público por parte de las personas con derecho a utilizarlos:', o:{a:'Constituye infracción de carácter muy grave.',b:'Constituye criterio de clasificación de una infracción como leve o grave.',c:'Constituye infracción de carácter grave.',d:'Constituye criterio de clasificación de una infracción como grave o muy grave.'}, correct:'a', why:{a:'La intensidad de la perturbación del uso de un servicio o espacio público por las personas con derecho a utilizarlos puede constituir infracción de carácter muy grave conforme al art. 140 LRBRL.'}},
{n:171, q:'En el ámbito de las infracciones a las Ordenanzas Locales, la intensidad de la perturbación ocasionada en el normal funcionamiento de un servicio público:', o:{a:'Constituye criterio de clasificación de una infracción como leve o grave.',b:'Constituye infracción de carácter muy grave.',c:'Constituye infracción de carácter grave.',d:'Constituye criterio de clasificación de una infracción como grave o muy grave.'}, correct:'c', why:{c:'La perturbación del normal funcionamiento de un servicio público constituye infracción de carácter grave conforme al art. 140 LRBRL.'}},
{n:172, q:'En el ámbito de las infracciones a las Ordenanzas Locales, la intensidad de los daños ocasionados a los equipamientos, infraestructuras, instalaciones o elementos de un servicio o de un espacio público:', o:{a:'Constituye infracción de carácter muy grave.',b:'Constituye infracción de carácter grave.',c:'Constituye criterio de clasificación de una infracción como leve o grave.',d:'Constituye criterio de clasificación de una infracción como grave o muy grave.'}, correct:'a', why:{a:'Los daños a equipamientos, infraestructuras o instalaciones de un servicio o espacio público constituyen infracción de carácter muy grave conforme al art. 140 LRBRL.'}},
{n:173, q:'El Municipio ostenta la potestad sancionadora en función de lo previsto:', o:{a:'En el artículo 41.f, de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',b:'En el artículo 4.1.f, de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',c:'En el artículo 126.1.c, de la Ley 7/1985, Reguladora de las Bases del Régimen Local.',d:'En el artículo 149.1.c, de la Ley 7/1985, Reguladora de las Bases del Régimen Local.'}, correct:'c', why:{c:'La potestad sancionadora del municipio está prevista en el art. 126.1.c) LRBRL, que la atribuye con carácter genérico al municipio.'}},
{n:174, q:'¿Qué órgano del Ayuntamiento ostenta, con carácter genérico, la potestad sancionadora del Municipio?', o:{a:'El Alcalde, en todo caso.',b:'La Junta de Gobierno Local en municipios de gran población y el Alcalde en los que no tengan esta condición.',c:'La Junta de Gobierno Local, en todo caso.',d:'La Junta de Gobierno Local en municipios que no sean de gran población y el Alcalde en los de gran población.'}, correct:'b', why:{b:'La potestad sancionadora genérica del municipio corresponde a la Junta de Gobierno Local en los municipios de gran población y al Alcalde en los de régimen común.'}},
{n:175, q:'En municipios que no sean de gran población la potestad sancionadora municipal la ostenta, con carácter genérico, el Alcalde, que será privado de la misma:', o:{a:'Solo cuando esta esté atribuida a otros órganos municipales de forma expresa, legal o reglamentariamente.',b:'El Alcalde no posee la potestad sancionadora del municipio.',c:'Nunca, salvo que la Junta de Gobierno Local así lo acuerde.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'En municipios de régimen común, el Alcalde ostenta la potestad sancionadora con carácter genérico y solo queda privado de ella cuando esté atribuida a otros órganos municipales de forma expresa, legal o reglamentariamente.'}},
{n:176, q:'En municipios de gran población ¿puede la Junta de Gobierno Local delegar el ejercicio de la potestad sancionadora?', o:{a:'La Junta de Gobierno Local no posee la potestad sancionadora en estos municipios.',b:'Sí.',c:'Sólo cuando esta potestad esté atribuida expresamente a otros órganos municipales, y a favor de los órganos determinados concretamente por la Ley.',d:'Solo en el Alcalde.'}, correct:'b', why:{b:'En municipios de gran población, la Junta de Gobierno Local posee la potestad sancionadora genérica y puede delegarla conforme a la LRBRL.'}},
{n:177, q:'En municipios de gran población, la Junta de Gobierno Local:', o:{a:'No tiene competencias en materia sancionadora.',b:'Tiene competencias en materia sancionadora pero no puede delegarlas.',c:'Solo puede delegar sus competencias sancionadoras en el Alcalde.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'En municipios de gran población, la Junta de Gobierno Local tiene competencias sancionadoras pero no puede delegarlas libremente; solo puede hacerlo en los supuestos y órganos previstos legalmente.'}},
{n:178, q:'En municipios de gran población, la Junta de Gobierno Local puede delegar sus competencias sancionadoras en:', o:{a:'Cualquier Concejal.',b:'Cualquier miembro de dicha Junta.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'En municipios de gran población, la Junta de Gobierno Local puede delegar sus competencias sancionadoras en cualquier Concejal conforme a la LRBRL.'}},
{n:179, q:'En municipios de gran población, la Junta de Gobierno Local puede delegar sus competencias sancionadoras en:', o:{a:'Los Coordinadores Generales.',b:'El Secretario General del Pleno.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'En municipios de gran población, la Junta de Gobierno Local puede delegar sus competencias sancionadoras en los Coordinadores Generales conforme a la LRBRL.'}},
{n:180, q:'En municipios de gran población, la Junta de Gobierno Local puede delegar sus competencias sancionadoras en:', o:{a:'Los Directores Generales.',b:'Cualquier miembro de dicha Junta.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'En municipios de gran población, la Junta de Gobierno Local puede delegar sus competencias sancionadoras en los Directores Generales y en cualquier miembro de la propia Junta conforme a la LRBRL.'}},
{n:181, q:'En municipios de régimen común ¿puede el Alcalde delegar el ejercicio de la potestad sancionadora?', o:{a:'El alcalde no posee la potestad sancionadora en estos municipios.',b:'Sí, puede delegarla en un Teniente de alcalde o Concejal.',c:'Sólo cuando esta potestad esté atribuida expresamente a otros órganos municipales, y a favor de los órganos determinados concretamente por la Ley.',d:'Solo en la Junta de Gobierno Local.'}, correct:'b', why:{b:'En municipios de régimen común, el Alcalde puede delegar el ejercicio de la potestad sancionadora en un Teniente de Alcalde o Concejal conforme a la LRBRL.'}},
{n:182, q:'La potestad sancionadora de los municipios:', o:{a:'Debe ejercerse con sujeción al principio de legalidad proclamado en el art.25 de la Constitución Española.',b:'Debe respetar los principios de tipicidad, seguridad jurídica, presunción de inocencia y proporcionalidad, separando debidamente la fase instructora de la sancionadora.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'La potestad sancionadora municipal debe respetar el principio de legalidad (art. 25 CE) y los principios de tipicidad, seguridad jurídica, presunción de inocencia y proporcionalidad, con separación de las fases instructora y sancionadora.'}},
{n:183, q:'Con respecto a la potestad sancionadora municipal, los tribunales se han pronunciado en diversas sentencias, siendo una de ellas:', o:{a:'STSJ de Baleares de 21/02/2002: La potestad sancionadora municipal deberá ejercerse con sujeción a las leyes de ámbito nacional, pero también respetando los acuerdos de sus órganos de gobierno.',b:'STSJ de Cataluña de 19/12/2007: El ejercicio de la potestad sancionadora no es discrecional para el órgano que debe ejercerla. No queda a su arbitrio sancionar o no, sino que ha de hacerlo por imperativo legal.',c:'STSJ de Castilla la Mancha de 17/12/2017: Los Ayuntamientos podrán ejercer la potestad sancionadora en materias propias de su competencia, pero no podrán hacerlo en aquellas materias que asuman tras ser delegadas por otras administraciones públicas.',d:'STSJ de Madrid de 12/01/2012: Los ayuntamientos no podrán ejercer la potestad sancionadora en aquellas materias que afecten a derechos fundamentales, aunque sí podrán participar en su ejercicio con la Comunidad Autónoma o el Estado.'}, correct:'d', why:{d:'La STSJ de Madrid de 12/01/2012 estableció que los ayuntamientos no pueden ejercer la potestad sancionadora en materias que afecten a derechos fundamentales, aunque pueden participar en su ejercicio con la CCAA o el Estado.'}},
{n:184, q:'La Ley 7/1985, Reguladora de las Bases del Régimen Local, establece los límites de las sanciones económicas por infracción de Ordenanzas locales:', o:{a:'En su art.141.',b:'En su art.41.',c:'En su art.126.',d:'En su art.136.'}, correct:'b', why:{b:'Los límites de las sanciones económicas por infracción de Ordenanzas locales están establecidos en el art. 141 LRBRL; según el solucionario la respuesta es b) (art. 41).'}},
{n:185, q:'Las multas por infracción de Ordenanzas Municipales, no podrán exceder, salvo previsión legal distinta, de:', o:{a:'1500 Euros en municipios que tengan entre 50.001 y 250.000 habitantes.',b:'750 Euros en municipios con población comprendida entre 20001 y 50.000 habitantes.',c:'3000 Euros, en municipios de más de 250.000 habitantes.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'El art. 141 LRBRL establece que las multas por infracción de Ordenanzas no podrán exceder de 3.000 euros en municipios de más de 250.000 habitantes.'}},
{n:186, q:'Las multas por infracciones graves de Ordenanzas Municipales no podrán exceder, salvo previsión legal distinta, de:', o:{a:'6.000 Euros.',b:'3.000 Euros.',c:'1.500 Euros.',d:'750 Euros.'}, correct:'c', why:{c:'El art. 141 LRBRL establece que las multas por infracciones graves de Ordenanzas no podrán exceder de 1.500 euros, salvo previsión legal distinta.'}},
{n:187, q:'Las multas por infracciones muy graves de Ordenanzas Municipales no podrán exceder, salvo previsión legal distinta, de:', o:{a:'6.000 Euros.',b:'3.000 Euros.',c:'1500 Euros.',d:'750 Euros.'}, correct:'b', why:{b:'El art. 141 LRBRL establece que las multas por infracciones muy graves de Ordenanzas no podrán exceder de 3.000 euros, salvo previsión legal distinta.'}},
{n:188, q:'Las multas por infracciones leves de Ordenanzas Municipales no podrán exceder, salvo previsión legal distinta, de:', o:{a:'6.000 Euros.',b:'3.000 Euros.',c:'1500 Euros.',d:'750 Euros.'}, correct:'d', why:{d:'El art. 141 LRBRL establece que las multas por infracciones leves de Ordenanzas no podrán exceder de 750 euros, salvo previsión legal distinta.'}},
{n:189, q:'Los Bandos de Alcaldía constituyen:', o:{a:'Una manifestación de la potestad sancionadora municipal.',b:'Una manifestación de la potestad reglamentaria municipal.',c:'Una potestad reservada al Ayuntamiento.',d:'Una manifestación de la potestad organizativa municipal.'}, correct:'b', why:{b:'Los Bandos de Alcaldía son una manifestación de la potestad reglamentaria municipal, mediante los cuales el Alcalde puede recordar obligaciones y publicar normas de su competencia.'}},
{n:190, q:'La diferencia entre un Bando y una Ordenanza o Reglamento radica:', o:{a:'En el órgano que los dicta.',b:'En las materias que regulan.',c:'No existen diferencias.',d:'Las respuestas a y b son correctas.'}, correct:'a', why:{a:'La diferencia entre un Bando y una Ordenanza o Reglamento radica principalmente en el órgano que los dicta: los Bandos los dicta el Alcalde, mientras que las Ordenanzas y Reglamentos los aprueba el Pleno.'}},
{n:191, q:'Para que un Bando pueda producir efectos:', o:{a:'Es necesario realizar el mismo trámite que para una Ordenanza.',b:'Solo se precisa que el Alcalde lo apruebe.',c:'Se precisa su publicación.',d:'Es necesario que la Junta de Gobierno Local lo apruebe.'}, correct:'c', why:{c:'Para que un Bando produzca efectos es necesaria su publicación; a diferencia de las Ordenanzas, no requiere los trámites de información pública ni aprobación plenaria.'}},
{n:192, q:'Los Bandos son normas dictadas y aprobadas por:', o:{a:'El Alcalde.',b:'El Alcalde en municipios de régimen común, y la Junta de Gobierno Local en municipios de gran población.',c:'La Junta de Gobierno Local.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'a', why:{a:'Los Bandos son dictados y aprobados por el Alcalde conforme al art. 21.1.e) LRBRL, con independencia del régimen del municipio.'}},
{n:193, q:'Los Alcaldes pueden dictar Bandos:', o:{a:'Sobre cualquier materia.',b:'Sólo sobre materias de titularidad exclusivamente municipal.',c:'Solamente para el desarrollo de las competencias que la ley les atribuye.',d:'Sobre las materias que le atribuya el Ayuntamiento Pleno al Alcalde.'}, correct:'c', why:{c:'Los Alcaldes pueden dictar Bandos solamente para el desarrollo de las competencias que la ley les atribuye, sin que puedan regular materias ajenas a sus atribuciones.'}},
{n:194, q:'Los Alcaldes pueden delegar la función de dictar Bandos en:', o:{a:'Los Tenientes de Alcalde.',b:'Los Concejales delegados del área de la materia que trate de regular el Bando.',c:'Cualquier miembro de la Corporación.',d:'Ninguna de las anteriores respuestas es correcta.'}, correct:'b', why:{b:'El Alcalde puede delegar la función de dictar Bandos en los Concejales delegados del área de la materia que trate de regular el Bando, conforme a la normativa de régimen local.'}},
{n:195, q:'Con respecto a los Bandos que puede dictar un Alcalde, indique la afirmación incorrecta:', o:{a:'La naturaleza jurídica del Bando no es crear derecho sino aplicar y recordar el derecho existente.',b:'Los Bandos dictados por los Alcaldes deben ser ratificados posteriormente por el pleno del respectivo Ayuntamiento.',c:'Los Bandos suelen ser recordatorios de obligaciones legales o reglamentarias.',d:'Pueden dar a conocer situaciones de interés o situaciones de hecho y solicitar la cooperación del vecindario ante acontecimientos festivos o eventos sociales.'}, correct:'b', why:{b:'La opción b) es incorrecta: los Bandos dictados por el Alcalde no requieren ratificación posterior por el Pleno del Ayuntamiento.'}},
{n:196, q:'En cuanto a los efectos jurídicos del Bando, la jurisprudencia se ha pronunciado de manera tajante en diversas sentencias. Indique cual de las siguientes no es una de ellas:', o:{a:'STS de 23/10/2002.',b:'STS de 09/04/2012: Determina que no cabe la posibilidad de que las ordenanzas contengan cláusulas de remisión a favor de la colaboración del alcalde mediante bandos.',c:'STSJ Madrid 586/2012 de 19 de abril.',d:'STSJ Madrid de 03/05/2001.'}, correct:'b', why:{b:'La STS de 09/04/2012 determinó que no cabe que las ordenanzas contengan cláusulas de remisión a favor de la colaboración del alcalde mediante bandos; esa sentencia trata sobre los límites de los bandos en relación con las ordenanzas.'}},
{n:197, q:'En cuanto a los efectos jurídicos del Bando, la jurisprudencia se ha pronunciado de manera tajante en diversas sentencias. Indique cual de las siguientes es una de ellas:', o:{a:'STSJ Madrid 586/2012 de 19 de abril: Determina que cabe la posibilidad de que las ordenanzas contengan cláusulas de remisión a favor de la colaboración del alcalde mediante bandos. Para su validez se precisa que la ordenanza aborde por sí misma el núcleo esencial de la regulación, de modo que la remisión a favor del bando no implique una abdicación, sino un verdadero complemento.',b:'STSJ Comunitat Valenciana 104/2002 de 6 de abril: Existe una posibilidad legal de regular a través de los bandos materias reservadas a ordenanzas, aunque su procedimiento de elaboración y aprobación generalmente se reserva al pleno de la corporación municipal, ya que supone mayores garantías de publicidad y audiencia de los administrados.',c:'STS de 18/05/2000: Los Alcaldes pueden dictar Bandos solamente para el desarrollo de las competencias que la ley les atribuye y, en todo caso, referidas a materias de titularidad municipal acordadas por el Pleno del Ayuntamiento.',d:'STS de 02/02/1991: El legislador puede aumentar o disminuir el número de materias que pueden desarrollarse a través de Bandos de Alcaldía, sin que por ello se interfiera en las competencias que tienen asumidas otros órganos municipales.'}, correct:'a', why:{a:'La STSJ Madrid 586/2012 de 19 de abril estableció que es válida la cláusula de remisión de ordenanzas a bandos siempre que la ordenanza aborde el núcleo esencial de la regulación y el bando actúe como complemento, no como abdicación.'}},
];
